import { describe, expect, it } from "vitest";
import { createRng, hashString } from "@/domain/shared/rng.js";

/**
 * mulberry32 and the string hash are the bottom of ADR-005: a save stores the
 * seed, and the world that seed describes is regenerated by calling
 * `createWorld` in `save.ts`. The sequence is therefore a FORMAT, not an implementation
 * detail — a change here silently relocates the terrain, the deposits and every
 * scheduled event of every save in flight.
 *
 * These values are pinned on purpose. A red here means "this edit changed the
 * world of the players' saves"; the answer is a migration, not a new number.
 */

describe("seeded rng (ADR-005)", () => {
  it("reproduces the same sequence for the same seed", () => {
    const a = createRng(12345);
    const b = createRng(12345);
    expect([a(), a(), a()]).toEqual([b(), b(), b()]);
  });

  it("keeps its published sequence stable across releases", () => {
    const rng = createRng(12345);
    expect([rng(), rng(), rng(), rng()]).toEqual([
      0.9797282677609473, 0.3067522644996643, 0.484205421525985,
      0.817934412509203,
    ]);
    // the value `world.ts` actually mixes in (hashString(seed) ^ 0x5e2d): its
    // first draws decide where the terrain of a fresh map lands
    const mixed = createRng(0x5e2d);
    expect([mixed(), mixed(), mixed()]).toEqual([
      0.0466065623331815, 0.321139334468171, 0.9375477754510939,
    ]);
  });

  it("hashes the whole string, its last character and its emptiness included", () => {
    // a loop that stops a byte early makes these two collide
    expect(hashString("nova")).not.toBe(hashString("novb"));
    expect(hashString("nova")).toBe(2173952735);
    expect(hashString("")).toBe(2166136261); // the FNV offset, with nothing folded in
  });
});
